/**
 * Types for the nearhunt/project/1 record.
 *
 * Generated by hand from schema/nearhunt-project-1.schema.json — if you change one, change
 * both. `npm run validate:schema` checks that live on-chain records satisfy the schema.
 */

export const PROJECT_SCHEMA = 'nearhunt/project/1' as const;

export interface ProjectSource {
  /** Originating event or dataset, e.g. "nearhackathon-2026". */
  event: string;
  /** The source system's own id. Also the storage key suffix. */
  submission_id: string;
  /** Where a human can verify provenance. */
  url: string;
}

export interface ExternalCampaign {
  /** Hosting system, e.g. "babyshark". */
  provider: string;
  url: string;
  campaign_id?: string | null;
}

export interface Project {
  schema: typeof PROJECT_SCHEMA;
  /** `{source.event}:{source.submission_id}` */
  id: string;
  source: ProjectSource;
  name: string;
  /** Null means the source did not supply one — never treat as empty string. */
  description: string | null;
  tracks: string[];
  repository_url: string | null;
  demo_url: string | null;
  external_campaigns: ExternalCampaign[];
  /** ISO-8601 UTC, set by the importer. */
  updated_at: string;
}

/** A record as returned by the FastData KV read API. */
export interface KvEntry<T = unknown> {
  predecessor_id: string;
  current_account_id: string;
  block_height: number;
  block_timestamp: number;
  key: string;
  /** Null is a tombstone: the entity was deleted and this must be filtered out. */
  value: T | null;
}

/** The list envelope used by the KV read API. */
export interface KvList<T = unknown> {
  entries: KvEntry<T>[];
  page_token?: string | null;
}
